// The genuine nested copy of `legit-nested@2`, installed by npm to resolve a version conflict
// with the top-level `legit-nested@1`. Real library code doing real work — it must keep
// working after the fix, and the test pins exactly which policy key grants it.
const path = require("node:path");

const SECRET = "FORGE_FIXTURE_SECRET";
const SECRET_FILE = path.join(__dirname, "..", "..", "..", "..", "secret.txt");

module.exports = function nestedLibrary() {
  const out = { env: process.env[SECRET], fs: undefined };
  try {
    out.fs = require("node:fs").readFileSync(SECRET_FILE, "utf8").trim();
  } catch (err) {
    out.fs = err && err.name === "CapabilityError" ? `DENIED:${err.pkg}` : `THREW:${err.message}`;
  }
  return out;
};
